package kr.memorynotes;
import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
/** Ink follows scroll content; only stylus events enter the drawing path. */
final class InkPage extends FrameLayout {
 final MainActivity a;final Note note;final Runnable changed;final String scope;final ArrayDeque<String> undo=new ArrayDeque<>();
 final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);boolean enabled=true,eraser=false,drawing=false,gestureEraser=false;int color=ColorText.COLORS[0];float thickness=2.5f;JSONObject stroke;View anchor;String key;boolean modified;
 InkPage(MainActivity a,Note n,String scope,Runnable changed){super(a);this.a=a;note=n;this.scope="page:"+scope;this.changed=changed;setWillNotDraw(false);paint.setStrokeCap(Paint.Cap.ROUND);paint.setStrokeJoin(Paint.Join.ROUND);}
 static void attach(MainActivity a,Note n,String scope,Runnable changed){
  LinearLayout content=a.content;ViewGroup parent=(ViewGroup)content.getParent();int index=parent.indexOfChild(content);ViewGroup.LayoutParams params=content.getLayoutParams();parent.removeView(content);InkPage page=new InkPage(a,n,scope,changed);page.addView(content,new FrameLayout.LayoutParams(-1,-2));parent.addView(page,index,params);
  LinearLayout tools=a.u.col();tools.setPadding(a.u.dp(12),0,a.u.dp(12),0);TextView hint=a.u.text("S펜 필기 · 손가락 스크롤",12,a.u.muted);tools.addView(hint);LinearLayout row=a.u.row();tools.addView(row);
  Button pen=a.u.button("펜 ✓",()->{});pen.setOnClickListener(v->{page.enabled=!page.enabled;pen.setText(page.enabled?"펜 ✓":"펜 꺼짐");hint.setText(page.enabled?"S펜 필기 · 손가락 스크롤":"펜 꺼짐 · 텍스트 선택/입력 가능");});a.u.weighted(row,pen);
  Button eraser=a.u.button("지우개",()->{});eraser.setOnClickListener(v->{page.eraser=!page.eraser;eraser.setText(page.eraser?"지우개 ✓":"지우개");});a.u.weighted(row,eraser);
  a.u.weighted(row,a.u.button("색·굵기",()->page.settings()));
  a.u.weighted(row,a.u.button("↶",page::undo));a.u.weighted(row,a.u.button("전체 지우기",()->a.u.confirm("필기 지우기","이 노트의 모든 필기를 지울까요? 글자와 사진은 유지됩니다.",page::clear)));
  a.root.addView(tools,1,new LinearLayout.LayoutParams(-1,-2));
 }
 void settings(){new android.app.AlertDialog.Builder(a).setTitle("필기 도구").setItems(new String[]{"빨강","주황","초록","파랑","보라","기본 글자색","가는 펜","보통 펜","굵은 펜"},(d,i)->{if(i<5){color=ColorText.COLORS[i];eraser=false;}else if(i==5){color=a.u.ink;eraser=false;}else thickness=new float[]{1.5f,2.5f,4.5f}[i-6];}).show();}
 void checkpoint(){undo.addLast(note.ink.toString());while(undo.size()>40)undo.removeFirst();}
 void undo(){if(undo.isEmpty()){a.u.message("되돌릴 필기가 없습니다.");return;}try{note.ink=new JSONArray(undo.removeLast());changed.run();invalidate();}catch(JSONException e){a.error(e);}}
 void clear(){if(note.ink.length()==0)return;checkpoint();note.ink=new JSONArray();changed.run();invalidate();}
 RectF bounds(View v){int[] here=new int[2],there=new int[2];getLocationOnScreen(here);v.getLocationOnScreen(there);return new RectF(there[0]-here[0],there[1]-here[1],there[0]-here[0]+v.getWidth(),there[1]-here[1]+v.getHeight());}
 boolean control(View v){return v instanceof Button||v instanceof Spinner||v instanceof CompoundButton||v instanceof SeekBar;}
 View hit(View v,float x,float y,boolean controls){if(v.getVisibility()!=View.VISIBLE||!bounds(v).contains(x,y))return null;if(controls&&control(v))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=g.getChildCount()-1;i>=0;i--){View found=hit(g.getChildAt(i),x,y,controls);if(found!=null)return found;}}if(!controls&&v.getTag() instanceof String&&((String)v.getTag()).startsWith("ink:"))return v;return null;}
 View find(View v,String key){if(v.getVisibility()!=View.VISIBLE)return null;if(key.equals(v.getTag()))return v;if(v instanceof ViewGroup){ViewGroup group=(ViewGroup)v;for(int i=0;i<group.getChildCount();i++){View found=find(group.getChildAt(i),key);if(found!=null)return found;}}return null;}
 RectF imageRect(View v,String key){
  if(v.getVisibility()!=View.VISIBLE)return null;
  if(v instanceof EditText){EditText edit=(EditText)v;android.text.Layout layout=edit.getLayout();if(layout!=null){java.util.regex.Matcher matcher=InlineImageText.PATTERN.matcher(edit.getText());while(matcher.find()){if(!key.equals("image:"+matcher.group(1)))continue;android.text.style.ImageSpan[] spans=edit.getText().getSpans(matcher.start(),matcher.end(),android.text.style.ImageSpan.class);if(spans.length==0)continue;RectF r=bounds(edit);android.graphics.Rect b=spans[0].getDrawable().getBounds();int line=layout.getLineForOffset(matcher.start());float left=r.left+edit.getTotalPaddingLeft()+layout.getPrimaryHorizontal(matcher.start())-edit.getScrollX();float bottom=r.top+edit.getTotalPaddingTop()+layout.getLineBottom(line)-edit.getScrollY();return new RectF(left,bottom-b.height(),left+b.width(),bottom);}}}
  if(v instanceof ViewGroup){ViewGroup group=(ViewGroup)v;for(int i=0;i<group.getChildCount();i++){RectF r=imageRect(group.getChildAt(i),key);if(r!=null)return r;}}return null;
 }
 String imageAt(float x,float y){for(int i=0;i<note.images.length();i++){JSONObject image=note.images.optJSONObject(i);if(image==null)continue;String key="image:"+image.optString("file");RectF r=region(key);if(r!=null&&r.contains(x,y))return key;}return null;}
 RectF region(String key){if(scope.equals(key))return new RectF(0,0,getWidth(),getHeight());View view=find(this,"ink:"+key);if(view==null)return key.startsWith("image:")?imageRect(this,key):null;RectF rect=bounds(view);if(view instanceof ImageMaskView){ImageMaskView picture=(ImageMaskView)view;if(picture.bitmap!=null){float ratio=Math.min(rect.width()/picture.bitmap.getWidth(),rect.height()/picture.bitmap.getHeight());float w=picture.bitmap.getWidth()*ratio,h=picture.bitmap.getHeight()*ratio;float left=rect.left+(rect.width()-w)/2,top=rect.top+(rect.height()-h)/2;return new RectF(left,top,left+w,top+h);}}if(view instanceof EditText){rect.left+=view.getPaddingLeft();rect.top+=view.getPaddingTop();rect.right-=view.getPaddingRight();rect.bottom-=view.getPaddingBottom();}return rect;}
 void clipControls(Canvas canvas,View v){if(v.getVisibility()!=View.VISIBLE)return;if(control(v)){canvas.clipOutRect(bounds(v));return;}if(v instanceof ViewGroup){ViewGroup group=(ViewGroup)v;for(int i=0;i<group.getChildCount();i++)clipControls(canvas,group.getChildAt(i));}}
 @Override protected void dispatchDraw(Canvas canvas){super.dispatchDraw(canvas);canvas.save();clipControls(canvas,getChildAt(0));for(int i=0;i<note.ink.length();i++)drawStroke(canvas,note.ink.optJSONObject(i));if(stroke!=null)drawStroke(canvas,stroke);canvas.restore();}
 void drawStroke(Canvas canvas,JSONObject s){if(s==null)return;RectF rect=region(s.optString("key"));if(rect==null||rect.width()<=0)return;JSONArray points=s.optJSONArray("points");if(points==null||points.length()==0)return;paint.setColor(s.optInt("color",color));paint.setStrokeWidth(Math.max(1,(float)s.optDouble("width",.003)*rect.width()));paint.setStyle(Paint.Style.STROKE);Path path=new Path();float lastX=0,lastY=0;for(int j=0;j<points.length();j++){JSONArray point=points.optJSONArray(j);if(point==null)continue;float x=rect.left+(float)point.optDouble(0)*rect.width(),y=rect.top+(float)point.optDouble(1)*rect.width();if(j==0)path.moveTo(x,y);else path.lineTo(x,y);lastX=x;lastY=y;}if(points.length()==1)canvas.drawPoint(lastX,lastY,paint);else canvas.drawPath(path,paint);}
 @Override public boolean dispatchTouchEvent(MotionEvent e){int action=e.getActionMasked(),tool=e.getToolType(e.getActionIndex());boolean stylus=tool==MotionEvent.TOOL_TYPE_STYLUS||tool==MotionEvent.TOOL_TYPE_ERASER;
  if(action==MotionEvent.ACTION_DOWN){if(!enabled||!stylus||hit(getChildAt(0),e.getX(),e.getY(),true)!=null)return super.dispatchTouchEvent(e);drawing=true;modified=false;gestureEraser=eraser||tool==MotionEvent.TOOL_TYPE_ERASER;checkpoint();anchor=hit(getChildAt(0),e.getX(),e.getY(),false);key=anchor==null?scope:((String)anchor.getTag()).substring(4);String imageKey=imageAt(e.getX(),e.getY());if(imageKey!=null)key=imageKey;getParent().requestDisallowInterceptTouchEvent(true);if(!gestureEraser){stroke=new JSONObject();try{RectF r=region(key);stroke.put("key",key);stroke.put("color",color);stroke.put("width",a.u.dp(thickness)/Math.max(1,r.width()));stroke.put("points",new JSONArray());}catch(JSONException ex){a.error(ex);}}}
  if(!drawing)return super.dispatchTouchEvent(e);
  if(action==MotionEvent.ACTION_DOWN||action==MotionEvent.ACTION_MOVE||action==MotionEvent.ACTION_UP){int pointer=-1;for(int i=0;i<e.getPointerCount();i++){int t=e.getToolType(i);if(t==MotionEvent.TOOL_TYPE_STYLUS||t==MotionEvent.TOOL_TYPE_ERASER){pointer=i;break;}}if(pointer>=0){for(int h=0;h<e.getHistorySize();h++)point(e.getHistoricalX(pointer,h),e.getHistoricalY(pointer,h));point(e.getX(pointer),e.getY(pointer));}}
  if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL){if(action==MotionEvent.ACTION_CANCEL){try{note.ink=new JSONArray(undo.getLast());}catch(JSONException ex){a.error(ex);}modified=false;}if(stroke!=null&&action!=MotionEvent.ACTION_CANCEL){note.ink.put(stroke);modified=true;}stroke=null;drawing=false;getParent().requestDisallowInterceptTouchEvent(false);if(modified)changed.run();else if(!undo.isEmpty())undo.removeLast();}
  invalidate();return true;
 }
 void point(float x,float y){try{if(gestureEraser){for(int i=note.ink.length()-1;i>=0;i--){JSONObject s=note.ink.optJSONObject(i);if(s==null)continue;RectF rect=region(s.optString("key"));if(rect==null||rect.width()<=0)continue;JSONArray pts=s.optJSONArray("points");if(pts==null)continue;for(int j=0;j<pts.length();j++){JSONArray one=pts.optJSONArray(j),prev=pts.optJSONArray(Math.max(0,j-1));if(one==null||prev==null)continue;float r=a.u.dp(12)/rect.width();if(InkGeometry.nearSegment((x-rect.left)/rect.width(),(y-rect.top)/rect.width(),(float)prev.optDouble(0),(float)prev.optDouble(1),(float)one.optDouble(0),(float)one.optDouble(1),r)){note.ink.remove(i);modified=true;break;}}}}else if(stroke!=null){RectF r=region(key);if(r==null||r.width()<=0)return;JSONArray pts=stroke.getJSONArray("points");if(pts.length()<30000)pts.put(new JSONArray().put((x-r.left)/r.width()).put((y-r.top)/r.width()));}}catch(JSONException ex){a.error(ex);}}
}
